<?php declare(strict_types=1); $base=config('app.base_path'); ?><div class="page-header"><div><h1>Edit Fresh Food Business</h1><p>Update profile, location, delivery and pre-order settings.</p></div><div class="page-actions"><a class="btn btn-secondary" href="<?= $base ?>/fresh-food/businesses/<?= (int)$record['id'] ?>">Back</a></div></div><?php if(!empty($error)): ?><div class="card"><p><?= htmlspecialchars((string)$error,ENT_QUOTES,'UTF-8') ?></p></div><?php endif; ?><form method="post" action="<?= $base ?>/fresh-food/businesses/<?= (int)$record['id'] ?>"><?php require __DIR__.'/form.php'; ?><div class="page-actions"><button class="btn btn-primary">Save Business</button></div></form>
<?php $days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];$by=[];foreach(($hours??[]) as $h)$by[(int)$h['day_of_week']]=$h; ?>
<div class="page-header"><div><h2>Operating Hours</h2><p>Set the normal operating window for this Fresh Food business.</p></div></div><form method="post" action="<?= $base ?>/fresh-food/businesses/<?= (int)$record['id'] ?>/hours"><div class="card" style="overflow:auto"><table class="table"><thead><tr><th>Day</th><th>Closed</th><th>Opens</th><th>Closes</th></tr></thead><tbody><?php foreach($days as $d=>$label):$h=$by[$d]??[];$closed=!empty($h['is_closed']); ?><tr><td><?= $label ?></td><td><input type="checkbox" class="ff-closed" data-day="<?= $d ?>" name="is_closed[<?= $d ?>]" value="1" <?= $closed?'checked':'' ?>></td><td><input class="ff-time" data-day="<?= $d ?>" type="time" name="opens_at[<?= $d ?>]" value="<?= htmlspecialchars(substr((string)($h['opens_at']??''),0,5),ENT_QUOTES,'UTF-8') ?>" <?= $closed?'disabled':'' ?>></td><td><input class="ff-time" data-day="<?= $d ?>" type="time" name="closes_at[<?= $d ?>]" value="<?= htmlspecialchars(substr((string)($h['closes_at']??''),0,5),ENT_QUOTES,'UTF-8') ?>" <?= $closed?'disabled':'' ?>></td></tr><?php endforeach; ?></tbody></table></div><div class="page-actions"><button class="btn btn-primary">Save Hours</button></div></form><script>document.querySelectorAll('.ff-closed').forEach(c=>{const sync=()=>document.querySelectorAll('.ff-time[data-day="'+c.dataset.day+'"]').forEach(i=>{i.disabled=c.checked;if(c.checked)i.value='';});c.addEventListener('change',sync);sync();});</script>
